import { act, fireEvent, render } from '@testing-library/react';
import { Profiler } from 'react';
import { expect, it } from 'vitest';
import { FilterList } from './Solution';

interface Frame {
  input: string;
  applied: string;
  highlight: string;
  rows: number;
}

const ROWS = ['apple pie', 'banana split', 'avocado toast', 'cherry lime', 'lime sorbet'];

const countFor = (query: string, rows: string[] = ROWS) =>
  rows.filter((row) => row.toLowerCase().includes(query.toLowerCase())).length;

/**
 * 帧探针：Profiler 的 onRender 在 commit 之后触发，此时读 DOM 拿到的就是"这一帧真正提交的内容"。
 * jsdom 没有布局与绘制，所以判"卡不卡"只能看提交序列与提交次数，绝不看墙钟耗时。
 */
function mount(rows: string[]) {
  const frames: Frame[] = [];
  const q = <T extends Element>(testid: string) => document.querySelector('[data-testid=' + testid + ']') as T | null;
  const record = () => {
    frames.push({
      input: q<HTMLInputElement>('query')?.value ?? '?',
      applied: q('applied')?.textContent ?? '?',
      highlight: q('highlight')?.textContent ?? '?',
      rows: q('rows')?.querySelectorAll('li').length ?? -1,
    });
  };
  render(
    <Profiler id="filter-list" onRender={() => record()}>
      <FilterList rows={rows} />
    </Profiler>,
  );
  const spin = async () => {
    await act(async () => {
      await new Promise((r) => setTimeout(r, 0));
    });
  };
  /** 输入后轮询到"新值已提交"为止：deferred 帧什么时候落地由 React 决定，不猜墙钟。 */
  const type = async (value: string) => {
    fireEvent.change(document.querySelector('[data-testid=query]') as HTMLInputElement, { target: { value } });
    for (let i = 0; i < 20; i += 1) {
      await spin();
      const f = frames[frames.length - 1];
      if (f && f.applied === value && f.rows === countFor(value, rows)) return;
    }
  };
  const last = (): Frame => frames[frames.length - 1];
  /** 滞后帧 = 这一帧 input 已经是新值、applied 还是旧值。 */
  const lagFrames = (value: string) => frames.filter((f) => f.input === value && f.applied !== value);
  const input = () => document.querySelector('[data-testid=query]') as HTMLInputElement;
  return { frames, input, type, last, lagFrames };
}

it('无数据输入时首帧渲染全部行且 applied 为空串', () => {
  const m = mount(ROWS);
  expect(m.frames.length).toBe(1);
  expect(m.last()).toEqual({ input: '', applied: '', highlight: '', rows: 5 });
});

it('单次输入的第一帧列表仍是旧结果', () => {
  const m = mount(ROWS);
  fireEvent.change(m.input(), { target: { value: 'li' } });
  expect(m.lagFrames('li').length).toBeGreaterThanOrEqual(1);
  expect(m.frames.some((f) => f.input === 'li' && f.applied === '' && f.rows === 5)).toBe(true);
});

it('下一帧收敛到新结果且 input 始终跟手', async () => {
  const m = mount(ROWS);
  await m.type('li');
  expect(m.last().input).toBe('li');
  expect(m.last().applied).toBe('li');
  expect(m.last().highlight).toBe('li');
  expect(m.last().rows).toBe(countFor('li'));
});

it('重复输入三帧里每帧 rows 都与本帧 applied 自洽（禁混合帧）', async () => {
  const m = mount(ROWS);
  await m.type('a');
  await m.type('ap');
  await m.type('a');
  const bad = m.frames.filter((f) => f.applied !== f.highlight || f.rows !== countFor(f.applied));
  expect(bad).toEqual([]);
  expect(m.frames.length).toBeGreaterThanOrEqual(4);
});

it('超大列表 3000 行时每次输入只多一帧且首帧滞后', async () => {
  const big = Array.from({ length: 3000 }, (_unused, i) => 'row ' + i + ' apple');
  const m = mount(big);
  await m.type('row 299');
  await m.type('row 2999');
  await m.type('row 1');
  const inputs = ['row 299', 'row 2999', 'row 1'];
  const lagged = inputs.filter((query) => m.lagFrames(query).length >= 1).length;
  expect(lagged).toBe(3);
  expect(m.frames.length).toBeLessThanOrEqual(12);
  expect(m.last().rows).toBe(countFor('row 1', big));
});

it('清空与无匹配都只渲染自洽帧', async () => {
  const m = mount(ROWS);
  await m.type('zz');
  expect(m.last().applied).toBe('zz');
  expect(m.last().rows).toBe(0);
  await m.type('');
  expect(m.last().applied).toBe('');
  expect(m.last().rows).toBe(5);
  const bad = m.frames.filter((f) => f.applied !== f.highlight || f.rows !== countFor(f.applied));
  expect(bad).toEqual([]);
});

