import { useDeferredValue, useMemo, useState } from 'react';

export interface FilterListProps {
  rows: string[];
}

export function FilterList({ rows }: FilterListProps) {
  const [query, setQuery] = useState('');
  /**
   * query：正确性关键（输入框的值），必须每帧跟手；
   * applied：可丢弃（列表过滤），允许先渲染旧值再补一帧。
   */
  const applied = useDeferredValue(query);
  const visible = useMemo(() => {
    const needle = applied.trim().toLowerCase();
    return needle ? rows.filter((row) => row.toLowerCase().includes(needle)) : rows;
  }, [rows, applied]);

  return (
    <div>
      <input data-testid="query" value={query} onChange={(event) => setQuery(event.target.value)} />
      <span data-testid="applied">{applied}</span>
      <span data-testid="highlight">{applied}</span>
      <ul data-testid="rows">
        {visible.map((row) => (
          <li key={row}>{row}</li>
        ))}
      </ul>
    </div>
  );
}

